python3 << 'PYEOF'
import json

# Load all registry definitions
defs = {}
for name, path in [('ixp', '/tmp/ixp_def.json'), ('end', '/tmp/end_def.json'),
                   ('switch', '/tmp/switch_def.json'), ('decision', '/tmp/decision_def.json'),
                   ('merge', '/tmp/merge_def.json'), ('script', '/tmp/script_def.json'),
                   ('agent', '/tmp/agent_def.json'), ('apiworkflow', '/tmp/apiworkflow_def.json'),
                   ('context', '/tmp/context_def.json')]:
    with open(path) as f:
        d = json.load(f)
    node = d.get('Data', {}).get('Node', d.get('Data', {}))
    defs[name] = node

# Load current flow to preserve CLI-authored sections
with open('BillingDisputeResolution.flow') as f:
    current = json.load(f)

# IDs
ANALYST_AGENT_ID = "35c19488-5b8b-43fc-92dc-904c140b14a2"
WRITER_AGENT_ID = "5b0fa1a7-fd44-48f3-a1ad-8d082634f033"
CONTEXT_RES_ID = "cc45b9b4-dbf6-47b3-40ac-08debc0cec5b"  # from node type

# IxP input defaults
ixp_defaults = defs['ixp'].get('inputDefaults', {})
ixp_model = ixp_defaults.get('model', {})
# Fix modelName if null
if not ixp_model.get('modelName'):
    ixp_model['modelName'] = ixp_model.get('modelDisplayName', 'invoices-billing')
ixp_output = defs['ixp'].get('outputDefinition', {})

# Build the complete flow
flow = {
  "id": current["id"],
  "version": "1.8",
  "name": "BillingDisputeResolution",
  "nodes": [
    # 1. Manual trigger
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {"label": "Manual trigger"},
      "inputs": {
        "entryPointId": current["nodes"][0]["inputs"]["entryPointId"],
        "isDefaultEntryPoint": True
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      }
    },
    # 2. IxP extraction
    {
      "id": "extractInvoice",
      "type": "uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178",
      "typeVersion": "1.0.0",
      "display": {"label": "Invoice Extraction (IxP)"},
      "inputs": {
        "model": ixp_model,
        "modelName": ixp_defaults.get('modelName', 'invoices-billing-f0c606f9-ixp'),
        "description": ixp_defaults.get('description', ''),
        "projectName": ixp_defaults.get('projectName', 'invoices-billing-f0c606f9-ixp'),
        "versionTag": "",
        "folderKey": ixp_defaults.get('folderKey', '79a7d12e-da84-4bf4-ab60-7f34b44dd178'),
        "folderName": ixp_defaults.get('folderName', 'Shared/uipath-maestro-flow/BillingDispute'),
        "fileRef": "=js:$vars.start.output.disputedInvoice",
        "pageRange": ""
      },
      "outputs": {
        "output": ixp_output.get("output", {"type": "object", "description": "IxP extraction result", "source": "=this.result", "var": "output"}),
        "error": ixp_output.get("error", {"type": "object", "description": "Error", "source": "=Error", "var": "error"})
      }
    },
    # 3. Normalize data script
    {
      "id": "normalizeData",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Normalize Data"},
      "inputs": {
        "script": """const result = $vars.extractInvoice.output;
const fields = (result && result.ExtractionResult && result.ExtractionResult.ResultsDocument && result.ExtractionResult.ResultsDocument.Fields) || [];
const normalized = fields.map(function(f) {
  return {
    Id: f.FieldId,
    Name: f.FieldName,
    Value: (f.Values && f.Values.length > 0) ? f.Values[0] : null,
    Type: f.FieldType,
    IsMissing: f.IsMissing,
    Confidence: f.Confidence
  };
});
return { fields: normalized };"""
      },
      "outputs": {
        "output": {"type": "object", "description": "Normalized IxP fields", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=result.Error", "var": "error"}
      }
    },
    # 4a. CRM Lookup (CLI-owned - already configured)
    current["nodes"][1],  # crmLookup1
    # 4b. ERP Lookup (CLI-owned - already configured)
    current["nodes"][3],  # erpLookup1
    # 5. Merge
    {
      "id": "mergeResults",
      "type": "core.logic.merge",
      "typeVersion": "1.0",
      "display": {"label": "Merge CRM + ERP"},
      "inputs": {}
    },
    # 6. Discrepancy detection script
    {
      "id": "detectDiscrepancies",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Discrepancy Detection"},
      "inputs": {
        "script": """const disputedItems = ($vars.start.output.webhookPayload && $vars.start.output.webhookPayload.dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems) || [];
const erpRecords = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) || ($vars.erpLookup1.output && $vars.erpLookup1.output.Value) || [];
var totalOvercharge = 0;
var totalUndercharge = 0;
var mismatches = [];
for (var i = 0; i < disputedItems.length; i++) {
  var item = disputedItems[i];
  var contractRow = null;
  for (var j = 0; j < erpRecords.length; j++) {
    var r = erpRecords[j];
    if (r && (r.lineNumber === item.lineNumber || r.LineNumber === item.lineNumber)) {
      contractRow = r;
      break;
    }
  }
  if (contractRow) {
    var contractPrice = contractRow.unitPrice || contractRow.UnitPrice || 0;
    var disputedPrice = item.unitPrice || 0;
    var qty = item.quantity || 1;
    var diff = (disputedPrice - contractPrice) * qty;
    if (diff > 0) {
      totalOvercharge += diff;
      mismatches.push({ lineNumber: item.lineNumber, type: 'overcharge', contractPrice: contractPrice, disputedPrice: disputedPrice, quantity: qty, diff: diff });
    } else if (diff < 0) {
      totalUndercharge += Math.abs(diff);
      mismatches.push({ lineNumber: item.lineNumber, type: 'undercharge', contractPrice: contractPrice, disputedPrice: disputedPrice, quantity: qty, diff: diff });
    }
  }
}
return { mismatches: mismatches, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge };"""
      },
      "outputs": {
        "output": {"type": "object", "description": "Discrepancy analysis", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=result.Error", "var": "error"}
      }
    },
    # 7. Dispute Analyst Agent (inline)
    {
      "id": "disputeAnalyst",
      "type": "uipath.agent.autonomous",
      "typeVersion": "1.2",
      "display": {"label": "Dispute Analyst Agent"},
      "inputs": {
        "systemPrompt": "You are a billing dispute analyst. Analyze invoice discrepancies and make a determination.",
        "userPrompt": "Analyze this billing dispute and return a structured determination.",
        "source": ANALYST_AGENT_ID,
        "agentInputVariables": [
          {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload", "description": "Webhook payload with dispute info"},
          {"id": "normalizeData__output__fields", "type": "array", "binding": "=$vars.normalizeData.output.fields", "description": "Normalized invoice fields"},
          {"id": "crmLookup1__output__output", "type": "object", "binding": "=$vars.crmLookup1.output", "description": "CRM account data"},
          {"id": "erpLookup1__output__output", "type": "object", "binding": "=$vars.erpLookup1.output", "description": "ERP contract data"},
          {"id": "detectDiscrepancies__output__mismatches", "type": "array", "binding": "=$vars.detectDiscrepancies.output.mismatches", "description": "Discrepancy analysis"},
          {"id": "detectDiscrepancies__output__totalOvercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalOvercharge", "description": "Total overcharge amount"},
          {"id": "detectDiscrepancies__output__totalUndercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalUndercharge", "description": "Total undercharge amount"}
        ],
        "agentOutputVariables": [
          {"id": "determination", "type": "string"},
          {"id": "recommendedAction", "type": "string"},
          {"id": "autoResolutionEligible", "type": "boolean"},
          {"id": "creditAmount", "type": "number"},
          {"id": "confidence", "type": "number"},
          {"id": "rationale", "type": "string"}
        ]
      },
      "outputs": {
        "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=Error", "var": "error"}
      }
    },
    # Resource node: context index for analyst agent
    {
      "id": "contextBillingSOPIndex",
      "type": "uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
      "typeVersion": "1.0.0",
      "display": {"label": "Billing Dispute SOP Index"},
      "inputs": {"source": CONTEXT_RES_ID}
    },
    # 8. Switch on recommendedAction
    {
      "id": "switchAction",
      "type": "core.logic.switch",
      "typeVersion": "1.1",
      "display": {"label": "Switch on Recommended Action"},
      "inputs": {
        "cases": [
          {"id": "escalate", "label": "Escalate to Manager", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'escalate_to_manager'"},
          {"id": "autoResolve", "label": "Auto Resolve", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'auto_resolve'"},
          {"id": "reject", "label": "Reject", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'reject'"}
        ]
      }
    },
    # 9a. Log Credit Amount script (auto_resolve path)
    {
      "id": "logCreditAmount",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Log Credit Amount"},
      "inputs": {
        "script": "return { creditAmount: $vars.disputeAnalyst.output.creditAmount };"
      },
      "outputs": {
        "output": {"type": "object", "description": "Credit amount", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=result.Error", "var": "error"}
      }
    },
    # 9b. Manager approval decision (escalate path)
    {
      "id": "managerApproval",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {"label": "Manager Approval"},
      "inputs": {
        "expression": "false",
        "trueLabel": "Rejected",
        "falseLabel": "Approved"
      }
    },
    # 9c. Financial posting API workflow (shared by auto_resolve and approved escalate)
    {
      "id": "financialPosting",
      "type": "uipath.core.api-workflow.07d45a91-9413-4dad-82ff-28306c2d85ea",
      "typeVersion": "1.0.0",
      "display": {"label": "FinancialPostingFunction"},
      "inputs": {
        "invoiceNumber": "=js:$vars.start.output.webhookPayload && $vars.start.output.webhookPayload.invoice ? $vars.start.output.webhookPayload.invoice.invoiceNumber : ''"
      },
      "outputs": {
        "output": {"type": "object", "description": "The return value of the API workflow", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=result.Error", "var": "error"}
      }
    },
    # 9d. Resolution Writer Agent (inline)
    {
      "id": "resolutionWriter",
      "type": "uipath.agent.autonomous",
      "typeVersion": "1.2",
      "display": {"label": "Resolution Writer Agent"},
      "inputs": {
        "systemPrompt": "You are a customer communications specialist. Draft resolution emails for billing disputes.",
        "userPrompt": "Draft a resolution email for this billing dispute.",
        "source": WRITER_AGENT_ID,
        "agentInputVariables": [
          {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload", "description": "Webhook payload with invoice info"},
          {"id": "disputeAnalyst__output__determination", "type": "string", "binding": "=$vars.disputeAnalyst.output.determination", "description": "Analyst determination"},
          {"id": "disputeAnalyst__output__creditAmount", "type": "number", "binding": "=$vars.disputeAnalyst.output.creditAmount", "description": "Approved credit amount"},
          {"id": "disputeAnalyst__output__rationale", "type": "string", "binding": "=$vars.disputeAnalyst.output.rationale", "description": "Analyst rationale"}
        ],
        "agentOutputVariables": [
          {"id": "subject", "type": "string"},
          {"id": "body", "type": "string"}
        ]
      },
      "outputs": {
        "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error", "source": "=Error", "var": "error"}
      }
    },
    # 10a. End - Return Resolution
    {
      "id": "endResolution",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "Return Resolution"},
      "inputs": {},
      "outputs": {
        "determination": {"source": "=js:$vars.disputeAnalyst.output.determination"},
        "recommendedAction": {"source": "=js:$vars.disputeAnalyst.output.recommendedAction"},
        "creditAmount": {"source": "=js:$vars.disputeAnalyst.output.creditAmount"},
        "rationale": {"source": "=js:$vars.disputeAnalyst.output.rationale"},
        "resolutionEmailBody": {"source": "=js:$vars.resolutionWriter.output.body"}
      }
    },
    # 10b. End - Return Rejection (reject path)
    {
      "id": "endRejection",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "Return Rejection"},
      "inputs": {},
      "outputs": {
        "determination": {"source": "=js:$vars.disputeAnalyst.output.determination"},
        "recommendedAction": {"source": "=js:$vars.disputeAnalyst.output.recommendedAction"},
        "creditAmount": {"source": "=js:$vars.disputeAnalyst.output.creditAmount"},
        "rationale": {"source": "=js:$vars.disputeAnalyst.output.rationale"},
        "resolutionEmailBody": {"source": "'No resolution email was drafted — dispute was rejected.'"}
      }
    },
    # 10c. End - Return Manager Rejection (rejected by manager)
    {
      "id": "endManagerRejection",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "Return Manager Rejection"},
      "inputs": {},
      "outputs": {
        "determination": {"source": "=js:$vars.disputeAnalyst.output.determination"},
        "recommendedAction": {"source": "=js:$vars.disputeAnalyst.output.recommendedAction"},
        "creditAmount": {"source": "=js:$vars.disputeAnalyst.output.creditAmount"},
        "rationale": {"source": "=js:$vars.disputeAnalyst.output.rationale"},
        "resolutionEmailBody": {"source": "'No resolution email was drafted — manager rejected the escalation.'"}
      }
    }
  ],
  "edges": [
    # start -> extractInvoice
    {"id": "e-start-ixp", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "extractInvoice", "targetPort": "input"},
    # extractInvoice -> normalizeData
    {"id": "e-ixp-normalize", "sourceNodeId": "extractInvoice", "sourcePort": "success", "targetNodeId": "normalizeData", "targetPort": "input"},
    # normalizeData -> crmLookup1 (fork to parallel)
    {"id": "e-normalize-crm", "sourceNodeId": "normalizeData", "sourcePort": "success", "targetNodeId": "crmLookup1", "targetPort": "input"},
    # normalizeData -> erpLookup1 (fork to parallel)
    {"id": "e-normalize-erp", "sourceNodeId": "normalizeData", "sourcePort": "success", "targetNodeId": "erpLookup1", "targetPort": "input"},
    # crmLookup1 -> mergeResults
    {"id": "e-crm-merge", "sourceNodeId": "crmLookup1", "sourcePort": "output", "targetNodeId": "mergeResults", "targetPort": "input"},
    # erpLookup1 -> mergeResults
    {"id": "e-erp-merge", "sourceNodeId": "erpLookup1", "sourcePort": "output", "targetNodeId": "mergeResults", "targetPort": "input"},
